using FastEndpoints; using Microsoft.AspNetCore.Diagnostics.HealthChecks; using Microsoft.EntityFrameworkCore; using Microsoft.Extensions.Diagnostics.HealthChecks; using OpenTelemetry.Metrics; using OpenTelemetry.Resources; using OpenTelemetry.Trace; using OrderFlow.Payments.Api.ExceptionHandling; using OrderFlow.Payments.Api.Middleware; using OrderFlow.Payments.Application; using OrderFlow.Payments.Infrastructure; using OrderFlow.Payments.Infrastructure.Persistence; using Serilog;
var builder=WebApplication.CreateBuilder(args);
builder.Services.AddSerilog((services,c)=>c.ReadFrom.Configuration(builder.Configuration).Enrich.FromLogContext().Enrich.WithProperty("Service","OrderFlow.Payments").Enrich.WithProperty("Environment",builder.Environment.EnvironmentName).WriteTo.Console());
builder.Services.AddApplication().AddInfrastructure(builder.Configuration);builder.Services.AddFastEndpoints();builder.Services.AddOpenApi();builder.Services.AddProblemDetails();builder.Services.AddExceptionHandler<ApiExceptionHandler>();
builder.Services.AddHealthChecks().AddCheck("self",()=>HealthCheckResult.Healthy(),tags:["live"]).AddDbContextCheck<PaymentsDbContext>("postgres",tags:["ready"]);
builder.Services.AddOpenTelemetry().ConfigureResource(r=>r.AddService("OrderFlow.Payments")).WithTracing(t=>t.AddAspNetCoreInstrumentation().AddHttpClientInstrumentation().AddSource("Microsoft.EntityFrameworkCore","Npgsql","OrderFlow.Payments.Kafka").AddOtlpExporter()).WithMetrics(m=>m.AddAspNetCoreInstrumentation().AddHttpClientInstrumentation().AddOtlpExporter());
var app=builder.Build();if(args.Contains("--migrate",StringComparer.OrdinalIgnoreCase)){await using var scope=app.Services.CreateAsyncScope();await scope.ServiceProvider.GetRequiredService<PaymentsDbContext>().Database.MigrateAsync();return;}app.UseMiddleware<CorrelationIdMiddleware>();app.UseSerilogRequestLogging();app.UseExceptionHandler();app.UseFastEndpoints();app.MapOpenApi();app.MapHealthChecks("/health/live",new HealthCheckOptions{Predicate=x=>x.Tags.Contains("live")});app.MapHealthChecks("/health/ready",new HealthCheckOptions{Predicate=x=>x.Tags.Contains("ready")});app.Run();
